export function createAdminPanel(api,{root,notice,selectPanel}){
 let tab=null,panel=null;
 function render(rows){const list=panel.querySelector('#admin-reports');list.replaceChildren();panel.querySelector('#admin-empty').hidden=Boolean(rows.length);for(const r of rows){const card=document.createElement('article');card.className='match-card';const h=document.createElement('h3');h.textContent='Zgłoszenie #'+r.report_id+' · '+r.status;const meta=document.createElement('p');meta.textContent='Zgłaszający: '+r.reporter_name+' · zgłoszona osoba: '+r.reported_name;const reason=document.createElement('p');reason.textContent=r.reason;const reviewed=document.createElement('button');reviewed.className='secondary';reviewed.textContent='Oznacz jako rozpatrzone';reviewed.disabled=r.status!=='open';reviewed.onclick=()=>review(r.report_id,'reviewed');const dismissed=document.createElement('button');dismissed.className='text-button';dismissed.textContent='Odrzuć zgłoszenie';dismissed.disabled=r.status!=='open';dismissed.onclick=()=>review(r.report_id,'dismissed');card.append(h,meta,reason,reviewed,dismissed);list.append(card);}}
 async function review(id,status){try{await api.reviewReport(id,status);notice(status==='reviewed'?'Zgłoszenie oznaczono jako rozpatrzone.':'Zgłoszenie odrzucono.');render(await api.adminReports());}catch(e){notice(e.message,true);}}
 async function init(){if(tab||!await api.isAdmin())return false;tab=document.createElement('button');tab.id='admin-tab';tab.className='tab';tab.type='button';tab.textContent='Moderacja';tab.setAttribute('aria-pressed','false');root.querySelector('nav.tabs').append(tab);panel=document.createElement('section');panel.id='admin-panel';panel.hidden=true;panel.innerHTML='<div class="card"><span class="step">TYLKO ADMINISTRATOR</span><h2>Moderacja zgłoszeń</h2><p class="muted">Panel nie pokazuje adresów e-mail. Decyzje są zapisywane z czasem i kontem administratora.</p><p id="admin-empty" class="muted">Brak zgłoszeń.</p><div id="admin-reports"></div></div>';root.insertBefore(panel,root.querySelector('#account-panel'));tab.onclick=async()=>{selectPanel('admin');render(await api.adminReports());};return true;}
 return{init,clear(){if(panel)panel.querySelector('#admin-reports')?.replaceChildren();}};
}
